def summarize_legacy_attendance(apps, schema_editor):
    alias = schema_editor.connection.alias
    Batch = apps.get_model('portal', 'AttendanceBatch')
    Daily = apps.get_model('portal', 'Attendance')
    Monthly = apps.get_model('portal', 'MonthlyAttendance')
    User = apps.get_model('portal', 'User')
    Batch.objects.using(alias).update(format_version=1)
    users = {user.pk: user for user in User.objects.using(alias).all().only('pk', 'username', 'full_name')}
    groups = (Daily.objects.using(alias).order_by().annotate(month=TruncMonth('date')).values('student_id', 'month')
              .annotate(clock_days=models.Count('pk', filter=models.Q(status__in=['normal', 'late'])),
                        leave_days=models.Count('pk', filter=models.Q(status='excused')), source_batch=models.Max('batch_id')))
    rows = []
    for group in groups.iterator():
        user = users[group['student_id']]
        rows.append(Monthly(student_id=user.pk, student_name=user.full_name, student_number=user.username,
            month=group['month'], clock_days=group['clock_days'], leave_days=group['leave_days'], batch_id=group['source_batch']))
        if len(rows) >= 500:
            Monthly.objects.using(alias).bulk_create(rows)
            rows = []
    Monthly.objects.using(alias).bulk_create(rows)


def prepare_legacy_batch_months(apps, schema_editor):
    # 降级前为跨月份的新批次恢复旧表必需的月份值；原月度表应从备份恢复，不能伪造每日明细。
    Batch = apps.get_model('portal', 'AttendanceBatch')
    qs = Batch.objects.using(schema_editor.connection.alias)
    for batch in qs.filter(month__isnull=True).iterator():
        qs.filter(pk=batch.pk).update(month=batch.created_at.date().replace(day=1))


